    const bassPattern = station.bass;
    if (step % 2 === 0) {
      const note = station.root - 12 + bassPattern[(step / 2) % bassPattern.length];
      this.tone(midiToFrequency(note), 0.26, station.kind === 'synth' ? 'sawtooth' : 'triangle', 0.075, time, this.musicBus);
